/*********************************************测试用例***********************************************
 * 环境准备：
 * 测试场景：
 *    验证$format - double
 * 测试步骤：
 *    1. $format取值324，发起查询
 *    2. $format取值338，发起查询
 *    3. $format取值339，发起查询
 *    4. $format取值340，发起查询
 * 期望结果：
 *    期望结果与实际结果一致，格式化输出字符串
 **************************************************************************************************/

testConf.skipStandAlone = true;
testConf.clName = COMMCLNAME + "_format_6";

main(test);
function test(args)
{
   var cl = args.testCL ;

   insertRecords(cl) ;
   var expRecords = expectRecords324();

   var actRecords = cl.find( {}, { "fieldName": { "$format": 324 } } ) ;
   commCompareResults( actRecords, expRecords ) ;

   var expRecords = expectRecords338();
   var actRecords = cl.find( {}, { "fieldName": { "$format": 338 } } ) ;
   commCompareResults( actRecords, expRecords ) ;

   var expRecords = expectRecords339();
   var actRecords = cl.find( {}, { "fieldName": { "$format": 339 } } ) ;
   commCompareResults( actRecords, expRecords ) ;

   var expRecords = expectRecords340();
   var actRecords = cl.find( {}, { "fieldName": { "$format": 340 } } ) ;
   commCompareResults( actRecords, expRecords ) ;

}

function insertRecords ( cl )
{
   var values = [ 4.94e-324, 4.9e-324, 5e-324, -4.94e-324, -4.9e-324, -5e-324 ] ;

   var docs = [];
   for( var i = 0; i < values.length; ++i )
   {
      var fieldValue = values[i];
      var objs = { "no": i, "fieldName": fieldValue };
      docs.push( objs );
   }
   cl.insert( docs );
}

function expectRecords324 ()
{
   var values = [ "0.",
         "0.",
         "0.",
         "-0.",
         "-0.",
         "-0." ] ;

   var docs = [];
   for( var i = 0; i < values.length; ++i )
   {
      var fieldValue = values[i];
      var objs = { "no": i, "fieldName": fieldValue };
      docs.push( objs );
   }
   return docs;
}

